    sections: [
      { heading: "1. かん字⑮（気・王・玉・音・夕・力）", body: "■ この かん字（6じ）\n・**気**（6かく）　よみ：き　ことば：「てんき・げんき」\n・**王**（4かく）　よみ：おう　ことば：「おうさま」\n・**玉**（5かく）　よみ：ぎょく・たま　ことば：「たま」\n・**音**（9かく）　よみ：おん・おと　ことば：「おと」\n・**夕**（3かく）　よみ：ゆう　ことば：「ゆうがた」\n・**力**（2かく）　よみ：りょく・ちから　ことば：「ちから」\n\n■ かきじゅん\nこの 下に、かん字ごとに 1かくずつ かきじゅんが 出ます。「つぎの かく」を おして、かたちと じゅんばんを たしかめよう。\n\n■ なぜ かきじゅんを まもるの？\nかきじゅんを まもると、かたちが ととのって、はやく きれいに かけるからです。\n\n★ ここがポイント：かん字は **かきじゅん**と **かくすう**で おぼえる。ことばと いっしょに おぼえる。", figureId: "u120k1_075_a", kanji: ["気", "王", "玉", "音", "夕", "力"] },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】「音」は なんかく？ よみかたと ことばを いおう\n\n【なぜ この やりかたかな】かくすう・よみ・ことばを いっしょに おぼえると、わすれにくいから。\n\n【ステップ1】「音」の かくすうを ゆびで かぞえる：9かく\n【ステップ2】よみ：おん・おと\n【ステップ3】ことば：おと\n\n【こたえ】9かく。よみは「おん・おと」。ことばは「おと」\n\n【たしかめ】かきじゅんの 画面で、1かくずつ かぞえて たしかめる。" },
      { heading: "3. よくある まちがい", body: "■ 「王」と「玉」を まちがえる\n\n「玉」は「王」の みぎしたに てんが ある。「王」は 4かく、「玉」は 5かく。\n\n■ なおしかた\n・てんの ありなしを 見る\n・かくすうを かぞえる（王4・玉5）\n\n★ ここがポイント：**ちがう ところを 1つ**見つける。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・「気・王・玉・音・夕・力」を、こえに だして よんで、くうに ゆびで かいてみよう\n・「王」と「玉」の ちがいを、おうちの 人に せつめいしてみよう\n\n■ おうちの人へ\n漢字は「空書き（指で空中になぞる）→ なぞり書き → 一人で書く」の順に練習すると定着します。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
    trapExamples: [{ question: "「玉」は なんかく？", wrongAnswer: "4かく", trapExplanation: "「王」と まちがえた。", correctAnswer: "5かく", correctExplanation: "「玉」は「王」に てんが ふえて 5かく。" }],
